def round_trip(n, edges):
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    parent = [-1] * (n + 1)
    seen = [False] * (n + 1)
    found = []

    def go(u, p):
        seen[u] = True
        parent[u] = p
