def round_trip_ii(n, edges):
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
    color = [0] * (n + 1)
    parent = [-1] * (n + 1)
    found = []

    def go(u):
        color[u] = 1
        for v in adj[u]:
            if found:
                return
            if color[v] == 1:
                cyc = [u]
                x = u
                while x != v:
                    x = parent[x]
                    cyc.append(x)
                cyc.reverse()
                cyc.append(cyc[0])
                found.append(cyc)
                return
            if color[v] == 0:
                parent[v] = u
                go(v)
        color[u] = 2

    for s in range(1, n + 1):
        if color[s] == 0 and not found:
            go(s)
    return found[0] if found else None


