def balanced_rec(parents, s):
    n = len(s)
    ch = children_of(n, parents)
    ans = 0

    def go(u):
        nonlocal ans
        total = 1 if s[u - 1] == "W" else -1
        for v in ch[u]:
            total += go(v)
        ans += total == 0
        return total

    go(1)
