def highest_score(parents):
    n = len(parents)
    ch = [[] for _ in range(n)]
    root = 0
    for v, p in enumerate(parents):
        if p == -1:
            root = v
        else:
            ch[p].append(v)
    sz = [1] * n

    def go(u):
        for v in ch[u]:
            go(v)
            sz[u] += sz[v]

    go(root)
    best = count = 0
    for v in range(n):
        prod = 1
        parts = 0
        for c in ch[v]:
            prod *= sz[c]
            parts += 1
        above = n - sz[v]
        if above:
            prod *= above
            parts += 1
        if parts == 0:
            prod = 0
        if prod > best:
            best, count = prod, 1
        elif prod == best:
            count += 1
    return count


def highest_score_index(parents):
    n = len(parents)
    root = parents.index(-1)
    sz = [1] * n
    for v in range(n - 1, 0, -1):
        if parents[v] != -1:
            sz[parents[v]] += sz[v]
    # The root has no piece above it. Broken sizes still change the count.
    ch = [[] for _ in range(n)]
    for v, p in enumerate(parents):
        if p != -1:
            ch[p].append(v)
    best = count = 0
    for v in range(n):
        prod = 1
        parts = 0
        for c in ch[v]:
            prod *= sz[c]
            parts += 1
        if v != root:
            prod *= n - sz[v]
            parts += 1
        if parts == 0:
            prod = 0
        if prod > best:
            best, count = prod, 1
        elif prod == best:
            count += 1
    return count


assert highest_score([-1, 2, 0, 2, 0]) == 3
assert highest_score([-1, 2, 0]) == 2
assert highest_score([-1]) == 1
assert highest_score([-1, 2, 3, 0]) == 2
assert highest_score_index([-1, 2, 3, 0]) == 1
