def highest_score_brute(parents):
    n = len(parents)
    adj = [[] for _ in range(n)]
    for v, p in enumerate(parents):
        if p != -1:
            adj[v].append(p)
            adj[p].append(v)
    best = count = 0
    for cut in range(n):
        seen = [False] * n
        seen[cut] = True
        prod = 1
        parts = 0
        for s in range(n):
            if seen[s]:
                continue
            q = deque([s])
            seen[s] = True
            comp = 0
            while q:
                u = q.popleft()
                comp += 1
                for v in adj[u]:
                    if not seen[v]:
