::: {#bcbdb6c8 .cell execution_count=37}
``` {.python .cell-code}
def ki(n, edges, ops):
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    parent = [-1] * (n + 1)
    parent[1] = 0
    order = []
    q = deque([1])
    while q:
        u = q.popleft()
        order.append(u)
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                q.append(v)
    cnt = [0] * (n + 1)
    for p, x in ops:
        cnt[p] += x
    for u in order:
        if u != 1:
            cnt[u] += cnt[parent[u]]
    return cnt[1:]


def ki_rec(n, edges, ops):
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    cnt = [0] * (n + 1)
    for p, x in ops:
        cnt[p] += x

    def go(u, p):
        for v in adj[u]:
            if v != p:
                cnt[v] += cnt[u]
                go(v, u)

    go(1, 0)
    return cnt[1:]


EDGES = [(1, 2), (2, 3), (2, 4)]
OPS = [(2, 10), (1, 100), (3, 1)]
assert ki(4, EDGES, OPS) == [100, 110, 111, 110]
assert ki_rec(4, EDGES, OPS) == [100, 110, 111, 110]
assert ki(1, [], [(1, 5)]) == [5]
```
