def ki_brute(n, edges, ops):
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    parent = [0] * (n + 1)

    def root(u, p):
        parent[u] = p
        for v in adj[u]:
            if v != p:
                root(v, u)

    root(1, 0)
    cnt = [0] * (n + 1)

    def under(u, p, x):
        cnt[u] += x
        for v in adj[u]:
            if v != p:
                under(v, u, x)

    for p, x in ops:
        under(p, parent[p], x)
    return cnt[1:]


