``` {.python .cell-code}
def count_descendants(n, parents, queries):
    ch = children_of(n, parents)
    tin = [0] * (n + 1)
    tout = [0] * (n + 1)
    dep = [0] * (n + 1)
    at = [[] for _ in range(n)]
    clock = 0

    def go(u):
        nonlocal clock
        tin[u] = clock
        at[dep[u]].append(clock)
        clock += 1
        for v in ch[u]:
            dep[v] = dep[u] + 1
            go(v)
        tout[u] = clock - 1

    go(1)
    ans = []
    for u, d in queries:
        if d >= n or d < dep[u]:
            ans.append(0)
            continue
        row = at[d]
        a, b = 0, len(row)
        while a < b:
            mid = (a + b) // 2
            if row[mid] < tin[u]:
                a = mid + 1
            else:
                b = mid
        lo = a
        a, b = 0, len(row)
        while a < b:
            mid = (a + b) // 2
            if row[mid] <= tout[u]:
                a = mid + 1
            else:
                b = mid
        ans.append(a - lo)
    return ans


