def count_descendants_walk(n, parents, queries):
    ch = children_of(n, parents)
    dep = [0] * (n + 1)

    def depths(u):
        for v in ch[u]:
            dep[v] = dep[u] + 1
            depths(v)

    depths(1)

    def under(u, d):
        total = int(dep[u] == d)

        def go(x):
            nonlocal total
            for v in ch[x]:
                total += int(dep[v] == d)
                go(v)

        go(u)
        return total

    return [under(u, d) for u, d in queries]


