``` {.python .cell-code}
def max_gold_prune(grid):
    g = [row[:] for row in grid]
    R, C = len(g), len(g[0])
    best = 0

    def go(r, c, got, left):
        nonlocal best
        val = g[r][c]
        got += val
        left -= val
        best = max(best, got)
        if got + left <= best:
            return
        g[r][c] = 0
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and g[nr][nc]:
                go(nr, nc, got, left)
        g[r][c] = val

    total = sum(sum(row) for row in g)
    for r in range(R):
        for c in range(C):
            if g[r][c]:
                go(r, c, 0, total)
    return best


