vector<vector<int>> getAncestors(int n, vector<vector<int>>& edges) {
    vector<vector<int>> rev(n);
    for (auto& e : edges) rev[e[1]].push_back(e[0]);
    vector<vector<int>> ans(n);
    for (int s = 0; s < n; s++) {
        vector<char> seen(n);
        vector<int> st = {s};
        while (!st.empty()) {
            int u = st.back();
            st.pop_back();
            for (int v : rev[u]) if (!seen[v]) {
                seen[v] = 1;
                st.push_back(v);
            }
        }
        for (int i = 0; i < n; i++)
            if (seen[i]) ans[s].push_back(i);
    }
    return ans;
}
