``` {.python .cell-code}
def ancestors_forward(n, edges):
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for u, v in edges:
        adj[u].append(v)
        indeg[v] += 1
    sets = [set() for _ in range(n)]
    q = deque(i for i in range(n) if indeg[i] == 0)
    while q:
        u = q.popleft()
        for v in adj[u]:
            sets[v].add(u)
            sets[v] |= sets[u]
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    return [sorted(s) for s in sets]


