``` {.python .cell-code}
def solve_maze(grid):
    g = [list(row) for row in grid]
    n, m = len(g), len(g[0])
    goods = []
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    for r in range(n):
        for c in range(m):
            if g[r][c] != "B":
                if g[r][c] == "G":
                    goods.append((r, c))
                continue
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if not (0 <= nr < n and 0 <= nc < m):
                    continue
                if g[nr][nc] == "G":
                    return False
                if g[nr][nc] == ".":
                    g[nr][nc] = "#"
    if not goods:
        return True
    er, ec = n - 1, m - 1
    if g[er][ec] == "#":
        return False
    seen = [[False] * m for _ in range(n)]
    seen[er][ec] = True
    q = deque([(er, ec)])
    reached = 0
    while q:
        r, c = q.popleft()
        if g[r][c] == "G":
            reached += 1
        if g[r][c] == "B":
            return False
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and not seen[nr][nc] and g[nr][nc] != "#":
                seen[nr][nc] = True
                q.append((nr, nc))
    return reached == len(goods)


