::: {#c51154f9 .cell execution_count=75}
``` {.python .cell-code}
def fuel(roads, seats):
    n = len(roads) + 1
    adj = [[] for _ in range(n)]
    for a, b in roads:
        adj[a].append(b)
        adj[b].append(a)
    parent = [-1] * n
    order = [0]
    i = 0
    while i < len(order):
        u = order[i]
        i += 1
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                order.append(v)
    sz = [1] * n
    total = 0
    for u in reversed(order):
        if u:
            total += (sz[u] + seats - 1) // seats
            sz[parent[u]] += sz[u]
    return total

