::: {#c3a15251 .cell execution_count=82}
``` {.python .cell-code}
def surrounded(board):
    g = [row[:] for row in board]
    R, C = len(g), len(g[0])

    def walk(r, c):
        if not (0 <= r < R and 0 <= c < C) or g[r][c] != "O":
            return
        g[r][c] = "S"
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            walk(r + dr, c + dc)

    for r in range(R):
        walk(r, 0)
        walk(r, C - 1)
    for c in range(C):
        walk(0, c)
        walk(R - 1, c)
    for r in range(R):
        for c in range(C):
            g[r][c] = "O" if g[r][c] == "S" else ("X" if g[r][c] == "O" else g[r][c])
    return g

board = [["X", "X", "X", "X"], ["X", "O", "O", "X"], ["X", "X", "O", "X"], ["X", "O", "X", "X"]]
assert surrounded(board) == [["X", "X", "X", "X"], ["X", "X", "X", "X"], ["X", "X", "X", "X"], ["X", "O", "X", "X"]]
