::: {#cba9c9d9 .cell execution_count=85}
``` {.python .cell-code}
def elect(n, edges):
    adj = [[] for _ in range(n + 1)]
    for u, v, bad in edges:
        adj[u].append((v, bad))
        adj[v].append((u, bad))
    chosen = []

    def go(u, p, bad_edge):
        covered = False
        for v, b in adj[u]:
            if v != p and go(v, u, b):
                covered = True
        if bad_edge and not covered:
            chosen.append(u)
            return True
        return covered

    go(1, 0, 0)
    return chosen

assert sorted(elect(5, [(1, 2, 1), (2, 3, 0), (1, 4, 0), (4, 5, 1)])) == [2, 5]
